module tb_release;reg clk=0;always #5 clk=~clk;reg rst_n=0,request=0,abort=0,ack_valid=0,ack_ok=0;reg [255:0] digest=1,ack_digest=1;reg [63:0] epoch=1,ack_epoch=1;wire release_pulse,pending;cih_release dut(.*);
initial begin @(negedge clk);rst_n=1;request=1;@(negedge clk);request=0;ack_valid=1;ack_ok=1;ack_digest=2;@(negedge clk);if(release_pulse||pending)$fatal;ack_valid=0;request=1;@(negedge clk);request=0;ack_valid=1;ack_digest=1;@(negedge clk);if(!release_pulse)$fatal;ack_valid=0;request=1;@(negedge clk);if(pending)$fatal;request=0;$display("CIH_RELEASE_PASS");$finish;end endmodule
